B.aju=new A.e(" Clause 9(a): The parties choose Option 2, \u201cGeneral Written Authorization\u201d and specify a time period of thirty (30) days.",!1,!1,!1,null)
B.a1Z=s([B.anz,B.aju],t.c)
B.anA=new A.e("11.3.2.3.",!0,!1,!1,null)
